// @name Sketchbook
// @background #fbf8f1
// @refresh 3600
// A sketchbook for a touch screen. Draw with a finger: pens in a calm
// palette, four brush sizes, an eraser, undo and redo. Drawings are saved as
// SVG files in the assets folder ("Drawings" by default), opened again from
// there, and can be drawn over a picture from the assets folder. The tools
// fold away into a corner to give the drawing the whole screen.
//
// How it draws: the page is a canvas (frameos.canvas) the size of the
// screen. A stroke is drawn into it once, as lines between the points the
// finger passes, and the frame repaints only those. The drawing itself is
// kept as strokes in the scene's state (the `drawing` field, on disk), and
// drawn again into a fresh canvas (a new interpreter, another look). Undo
// puts back the box the last stroke covered: paper, picture and the strokes
// that cross it, clipped to the box, so it costs what is there, not the
// whole drawing.
import { Icon, ICONS, Sheet, SheetBar, Action, FileRow, NameForm, setZoom, z } from './ui'
import {
  safeName, safeFolder, listFiles, listFolder, writeText, readText, svgRoot, svgElements, svgTitle,
  numbers, pathRuns, hexColor, xml, baseName, stripExt,
} from './files'
import { strokeBox, unionBox, boxesMeet, capsuleStrips, mergeStrips, pointCount } from './ink'

// Pens: calm, deep tones and white (to draw over a picture). High contrast
// draws black, and white as an eraser that also works over a picture.
const PENS = ['#262626', '#1e3a8a', '#0284c7', '#0f766e', '#4d7c0f', '#ca8a04', '#c2410c', '#be123c', '#7e22ce', '#ffffff']
const PEN_NAMES = ['Charcoal', 'Navy', 'Sky', 'Teal', 'Forest', 'Ochre', 'Terracotta', 'Crimson', 'Plum', 'White']
const HC_PENS = ['#000000', '#ffffff']
const SIZES = [3, 6, 12, 24] // brush widths at 480 px of the drawing's shorter side
const SIZE_NAMES = ['Fine', 'Medium', 'Bold', 'Marker']
const MAX_POINTS = 5000 // a drawing's points, kept in state and drawn again into a fresh canvas
const IMAGES = ['.png', '.jpg', '.jpeg']

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    desk: '#cbd5e1',
    rail: 'bg-slate-800 text-white rounded-2xl',
    tool: 'text-white active:bg-white/20',
    toolOn: 'bg-amber-300 text-slate-900',
    toolOff: 'text-slate-500',
    panel: 'bg-slate-800 text-white rounded-2xl',
    swatch: 'border-2 border-white/30',
    swatchOn: 'border-4 border-amber-300',
    sizeOn: 'bg-amber-300 text-slate-900',
    size: 'bg-white/10 text-white',
    cover: 'bg-slate-900/40',
    sheet: 'bg-white text-slate-800',
    bar: 'bg-slate-100',
    ghost: 'active:bg-slate-200',
    muted: 'text-slate-500',
    button: 'bg-slate-100 text-slate-800 active:bg-slate-200',
    primary: 'bg-slate-800 text-white active:bg-slate-700',
    danger: 'bg-rose-700 text-white active:bg-rose-800',
    row: 'bg-slate-50 active:bg-slate-100',
    field: 'bg-slate-100 focus:bg-sky-50',
    accentText: 'text-amber-600',
    note: 'bg-slate-800 text-white',
    hint: 'text-slate-400',
    dot: 'bg-amber-300',
  },
  high: {
    desk: '#ffffff',
    rail: 'bg-white text-black border-2 border-black rounded-2xl',
    tool: 'text-black',
    toolOn: 'bg-black text-white',
    toolOff: 'text-black',
    panel: 'bg-white text-black border-2 border-black rounded-2xl',
    swatch: 'border-2 border-black',
    swatchOn: 'border-4 border-black',
    sizeOn: 'bg-black text-white',
    size: 'bg-white text-black border-2 border-black',
    cover: '',
    sheet: 'bg-white text-black border-4 border-black',
    bar: 'bg-white border-b-2 border-black',
    ghost: '',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    danger: 'bg-black text-white',
    row: 'bg-white border-2 border-black',
    field: 'bg-white border-2 border-black',
    accentText: 'text-black',
    note: 'bg-black text-white',
    hint: 'text-black',
    dot: 'bg-black',
  },
}

// ------------------------------------------------------------------ state

// The drawing, in the scene's state (`drawing`, private, on disk): its
// file name ('' before it is saved), its size in its own units, the
// picture under it, the strokes ([color, width, x0, y0, ...], color '' for
// the eraser), a revision count and the revision last saved. `gen` changes
// when the whole drawing does (opened, cleared, a new picture), which the
// canvas notices and draws it again.
let doc = null
const blank = (w, h) => ({ name: '', w, h, bg: '', strokes: [], rev: 0, saved: 0, gen: 0 })
const loadDoc = (app, w, h) => {
  const kept = app.state.drawing
  if (kept && typeof kept === 'object' && Array.isArray(kept.strokes) && kept.w > 0 && kept.h > 0) return kept
  return blank(w, h)
}
const commit = () => frameos.setState('drawing', doc)
const changed = () => {
  doc.rev = (doc.rev || 0) + 1
  commit()
}

// The tools and what is open: the app's own, between renders.
let ui = null
const UI_DEFAULTS = { panel: '', tool: 'pen', pen: 0, size: -1, collapsed: false, browse: '', draft: '', asking: '', note: '' }
const loadUi = () => Object.assign({}, UI_DEFAULTS, frameos.recall('ui') || {})
const setUi = (patch) => {
  Object.assign(ui, patch)
  frameos.remember('ui', ui)
}
// Redo: strokes Undo took back, until the next stroke.
const redoStack = () => frameos.recall('redo') || []

// Settings, read once per render.
let paper = '#fbf8f1'
let folder = 'Drawings'
let hc = false
let T = THEMES.color

// ------------------------------------------------------------------ view

// The canvas is the screen, W x H in the UI's pixels and k times that in
// its own (render scale). The drawing sits in it at scale s, centered.
let W = 800
let H = 480
let k = 1
let CW = 800
let CH = 480
let s = 1
let ox = 0
let oy = 0
let canvas = null
let picture = null // { path, ref } the background picture, kept while the interpreter lives

const fitView = () => {
  s = Math.min(W / doc.w, H / doc.h)
  ox = (W - doc.w * s) / 2
  oy = (H - doc.h * s) / 2
}
// Drawing units to canvas pixels.
const cs = () => s * k
const px = (v, o) => v * s * k + o * k
const docX = (x) => Math.round(((x - ox) / s) * 2) / 2
const docY = (y) => Math.round(((y - oy) / s) * 2) / 2
const unit = () => Math.min(doc.w, doc.h) / 480

const inkOf = (color) => {
  if (!color) return paperColor()
  if (hc) return color.toLowerCase() === '#ffffff' ? '#ffffff' : '#000000'
  return color
}
const paperColor = () => (hc ? '#ffffff' : paper)
const pens = () => (hc ? HC_PENS : PENS)
const brushWidth = () => SIZES[ui.size] * unit()
const eraserWidth = () => (SIZES[ui.size] * 2 + 10) * unit()

// The background picture, decoded once at the drawing's size in the canvas.
const backgroundRef = () => {
  if (!doc.bg) return null
  if (picture && picture.path === doc.bg && picture.w === CW && picture.h === CH) return picture.ref
  if (picture) frameos.releaseImage(picture.ref)
  const ref = frameos.loadAssetImage(doc.bg, {
    keep: true,
    width: Math.max(1, Math.round(doc.w * cs())),
    height: Math.max(1, Math.round(doc.h * cs())),
    fit: 'cover',
  })
  picture = ref ? { path: doc.bg, ref, w: CW, h: CH } : null
  if (!ref) note(`The picture ${doc.bg} could not be opened`)
  return ref
}
const PictureEl = ({ bgRef }) => (
  <image href={bgRef} x={px(0, ox)} y={px(0, oy)} width={Math.round(doc.w * cs())} height={Math.round(doc.h * cs())}
    preserveAspectRatio="none" />
)

// One stroke as SVG in canvas pixels. The eraser paints the paper, or over
// a picture puts the picture back, strip by strip along its band.
const strokeEl = (stroke, bgRef) => {
  const color = stroke[0]
  const width = Number(stroke[1]) * cs()
  if (!color && bgRef) {
    let strips = []
    const step = Math.max(2, Math.round(width / 6))
    const last = stroke.length - 2
    for (let i = 2; i <= last; i += 2) {
      const j = i + 2 <= last ? i + 2 : i
      if (i === j && i > 2) break
      const a = [px(stroke[i], ox), px(stroke[i + 1], oy), px(stroke[j], ox), px(stroke[j + 1], oy)]
      for (const r of capsuleStrips(a[0], a[1], a[2], a[3], width / 2, step)) strips.push(r)
    }
    strips = mergeStrips(strips)
    return (
      <g>
        {strips.map(([x, y, w, h]) => (
          <svg x={x} y={y} width={w} height={h} viewBox={`${x} ${y} ${w} ${h}`}>
            <rect x={x} y={y} width={w} height={h} fill={paperColor()} />
            <PictureEl bgRef={bgRef} />
          </svg>
        ))}
      </g>
    )
  }
  const ink = inkOf(color)
  if (stroke.length <= 4) {
    return <circle cx={px(stroke[2], ox)} cy={px(stroke[3], oy)} r={width / 2} fill={ink} />
  }
  const points = []
  for (let i = 2; i + 1 < stroke.length; i += 2) points.push(Math.round(px(stroke[i], ox) * 10) / 10, Math.round(px(stroke[i + 1], oy) * 10) / 10)
  return <polyline points={points.join(' ')} fill="none" stroke={ink} strokeWidth={width} strokeLinecap="round" strokeLinejoin="round" />
}

// The whole drawing into the canvas: the desk, the paper, the picture, the
// strokes (a few dozen to a draw call).
const paintAll = () => {
  frameos.clear(canvas, T.desk)
  frameos.draw(canvas, <rect x={px(0, ox)} y={px(0, oy)} width={doc.w * cs()} height={doc.h * cs()} fill={paperColor()} />)
  const bgRef = backgroundRef()
  if (bgRef) frameos.draw(canvas, <PictureEl bgRef={bgRef} />)
  // Pen strokes a few dozen to a draw call; an eraser over a picture alone
  // (it is many small clips), so no call holds a big tree.
  let batch = []
  const flush = () => {
    if (batch.length) frameos.draw(canvas, <g>{batch}</g>)
    batch = []
  }
  for (const stroke of doc.strokes) {
    if (!stroke[0] && bgRef) {
      flush()
      frameos.draw(canvas, strokeEl(stroke, bgRef))
    } else {
      batch.push(strokeEl(stroke, bgRef))
      if (batch.length >= 40) flush()
    }
  }
  flush()
}

// One box of the drawing (its units) again: what is there, clipped to it.
const repaint = (box) => {
  const x0 = Math.max(0, Math.floor(px(box[0], ox)) - 1)
  const y0 = Math.max(0, Math.floor(px(box[1], oy)) - 1)
  const x1 = Math.min(CW, Math.ceil(px(box[2], ox)) + 1)
  const y1 = Math.min(CH, Math.ceil(px(box[3], oy)) + 1)
  if (x1 <= x0 || y1 <= y0) return
  const bgRef = backgroundRef()
  const inside = doc.strokes.filter((stroke) => boxesMeet(strokeBox(stroke), box))
  frameos.draw(canvas, (
    <g>
      <svg x={x0} y={y0} width={x1 - x0} height={y1 - y0} viewBox={`${x0} ${y0} ${x1 - x0} ${y1 - y0}`}>
        <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill={T.desk} />
        <rect x={px(0, ox)} y={px(0, oy)} width={doc.w * cs()} height={doc.h * cs()} fill={paperColor()} />
        {bgRef ? <PictureEl bgRef={bgRef} /> : null}
        {inside.map((stroke) => strokeEl(stroke, bgRef))}
      </svg>
    </g>
  ))
}

// ---------------------------------------------------------------- actions

const note = (text) => setUi({ note: text })

const undo = () => {
  if (!doc.strokes.length) return
  const stroke = doc.strokes.pop()
  const redo = redoStack()
  redo.push(stroke)
  frameos.remember('redo', redo.slice(-60))
  if (canvas) repaint(strokeBox(stroke))
  else doc.gen = (Number(doc.gen) || 0) + 1 // no canvas here: the next render draws it all
  changed()
}
const redo = () => {
  const redo = redoStack()
  if (!redo.length) return
  const stroke = redo.pop()
  frameos.remember('redo', redo)
  doc.strokes.push(stroke)
  if (canvas) frameos.draw(canvas, strokeEl(stroke, backgroundRef()))
  else doc.gen = (Number(doc.gen) || 0) + 1
  changed()
}
// Something that changes the whole drawing: the canvas draws it again.
const replaced = (next) => {
  next.gen = (Number(doc.gen) || 0) + 1
  doc = next
  frameos.remember('redo', [])
  commit()
}

// The live stroke, while a finger is down: kept with remember as well, so
// it survives a new interpreter between two moves.
let live = null
const liveStroke = () => live || frameos.recall('live') || null
const setLive = (stroke) => {
  live = stroke
  frameos.remember('live', stroke)
}

const startStroke = (e) => {
  if (ui.panel || ui.note) {
    setUi({ panel: '', note: '' })
    if (ui.panel) return
  }
  if (pointCount(doc.strokes) >= MAX_POINTS) {
    note('This drawing is full: save it and start a new one')
    return
  }
  const x = docX(e.localX)
  const y = docY(e.localY)
  const eraser = ui.tool === 'eraser'
  const stroke = [eraser ? '' : pens()[ui.pen] || pens()[0], Math.round((eraser ? eraserWidth() : brushWidth()) * 10) / 10, x, y]
  setLive(stroke)
  frameos.draw(canvas, strokeEl(stroke, eraser ? backgroundRef() : null))
}
const moveStroke = (e) => {
  const stroke = liveStroke()
  if (!stroke || !canvas) return
  const x = docX(e.localX)
  const y = docY(e.localY)
  const lx = stroke[stroke.length - 2] as number
  const ly = stroke[stroke.length - 1] as number
  // Points closer than a third of the brush add nothing a finger can see.
  const near = Math.max(1.5, Number(stroke[1]) / 5)
  if (Math.abs(x - lx) + Math.abs(y - ly) < near) return
  frameos.draw(canvas, strokeEl([stroke[0], stroke[1], lx, ly, x, y], stroke[0] ? null : backgroundRef()))
  stroke.push(x, y)
  setLive(stroke)
}
const endStroke = () => {
  const stroke = liveStroke()
  if (!stroke) return
  setLive(null)
  doc.strokes.push(stroke)
  frameos.remember('redo', [])
  changed()
}

// ----------------------------------------------------------------- files

const pathOf = (name) => `${folder}/${name}.svg`

// The drawing as an SVG file: a plain picture anywhere (one polyline per
// stroke, round caps and joins), with what the sketchbook needs to open it
// again in data- attributes: the paper, the picture under it, the eraser.
const svgText = (name) => {
  const pc = paper
  const lines = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${doc.w}" height="${doc.h}" viewBox="0 0 ${doc.w} ${doc.h}"` +
      ` data-frameos="sketchbook" data-paper="${pc}"${doc.bg ? ` data-background="${xml(doc.bg)}"` : ''}>`,
    `<title>${xml(name)}</title>`,
    `<desc>Drawn in the FrameOS Sketchbook${doc.bg ? ` over the picture ${xml(doc.bg)} (assets folder)` : ''}.</desc>`,
    `<rect width="${doc.w}" height="${doc.h}" fill="${pc}"/>`,
  ]
  for (const stroke of doc.strokes) {
    const color = stroke[0] || pc
    const tool = stroke[0] ? '' : ' data-tool="eraser"'
    if (stroke.length <= 4) {
      lines.push(`<circle cx="${stroke[2]}" cy="${stroke[3]}" r="${Number(stroke[1]) / 2}" fill="${color}"${tool}/>`)
    } else {
      const points = []
      for (let i = 2; i + 1 < stroke.length; i += 2) points.push(`${stroke[i]},${stroke[i + 1]}`)
      lines.push(`<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="${stroke[1]}"` +
        ` stroke-linecap="round" stroke-linejoin="round"${tool}/>`)
    }
  }
  lines.push('</svg>')
  return lines.join('\n') + '\n'
}

// An SVG file back into strokes: ours exactly, and the lines, polylines,
// simple paths and dots of others as strokes. What it does not know (fills,
// text, transforms) it leaves out.
const parseDrawing = (text) => {
  const root = svgRoot(text || '')
  if (!root) return null
  const strokes = []
  const q = (v) => Math.round(v * 2) / 2
  for (const [tag, a] of svgElements(text, ['polyline', 'polygon', 'line', 'path', 'circle'])) {
    const eraser = a['data-tool'] === 'eraser'
    if (tag === 'circle') {
      const fill = hexColor(a.fill)
      const r = parseFloat(a.r)
      if ((fill || eraser) && r > 0) strokes.push([eraser ? '' : fill, q(r * 2), q(parseFloat(a.cx || '0') - root.x), q(parseFloat(a.cy || '0') - root.y)])
      continue
    }
    const color = eraser ? '' : hexColor(a.stroke)
    if (!color && !eraser) continue
    const width = q(parseFloat(a['stroke-width']) || 1)
    let runs = []
    if (tag === 'line') runs = [[a.x1, a.y1, a.x2, a.y2].map((v) => parseFloat(v || '0'))]
    else if (tag === 'path') runs = pathRuns(a.d)
    else {
      const pts = numbers(a.points)
      if (tag === 'polygon' && pts.length >= 4) pts.push(pts[0], pts[1])
      runs = [pts]
    }
    for (const run of runs) {
      if (run.length < 2) continue
      const stroke = [color, width]
      for (let i = 0; i + 1 < run.length; i += 2) stroke.push(q(run[i] - root.x), q(run[i + 1] - root.y))
      strokes.push(stroke)
    }
  }
  return { w: root.w, h: root.h, bg: root.attrs['data-background'] || '', title: svgTitle(text), strokes }
}

const save = (name) => {
  const ok = writeText(pathOf(name), svgText(name))
  if (!ok) {
    note('Could not save: does the scene have the "writes assets folder" permission?')
    return false
  }
  doc.name = name
  doc.saved = doc.rev
  commit()
  note(`Saved ${pathOf(name)}`)
  return true
}

const open = (path) => {
  const parsed = parseDrawing(readText(path))
  if (!parsed) {
    note(`${baseName(path)} is not a drawing this can open`)
    return
  }
  let strokes = parsed.strokes
  let cut = false
  while (pointCount(strokes) > MAX_POINTS) {
    strokes = strokes.slice(0, Math.floor(strokes.length * 0.9))
    cut = true
  }
  replaced({ name: stripExt(baseName(path)), w: parsed.w, h: parsed.h, bg: parsed.bg, strokes, rev: 0, saved: 0, gen: doc.gen })
  setUi({ panel: '', asking: '', note: cut ? 'Only the first strokes fit; the file is unchanged' : `Opened ${baseName(path)}` })
}

// "Drawing 3": the first name not taken in the folder.
const freshName = () => {
  const taken = listFiles(folder, ['.svg']).map((path) => stripExt(baseName(path)).toLowerCase())
  for (let n = 1; ; n++) if (!taken.includes(`drawing ${n}`)) return `Drawing ${n}`
}

// --------------------------------------------------------------- the rail

const Tool = ({ d, on, off, onClick, b, children }) => (
  <div className={`w-[${b}px] h-[${b}px] shrink-0 flex items-center justify-center rounded-xl ${on ? T.toolOn : off ? T.toolOff : T.tool}`}
    onClick={onClick}>
    {children || <Icon d={d} className={`w-[${Math.round(b * 0.5)}px] h-[${Math.round(b * 0.5)}px]`} />}
  </div>
)

// The tools, along the side (or the bottom of a tall screen). memo: drawn
// again only when what it shows changes, not with every stroke.
const Rail = memo(({ b, across, lefty, tool, pen, size, canUndo, canRedo, dirty, hcLook }) => {
  const color = pens()[pen] || pens()[0]
  const dot = Math.max(4, Math.round((SIZES[size] / 24) * b * 0.42))
  return (
    <div className={`flex ${across ? 'flex-row' : 'flex-col'} gap-[6px] p-[6px] ${T.rail}`} onPointerDown={() => {}}>
      <Tool b={b} d={across ? ICONS.down : lefty ? ICONS.right : ICONS.left} onClick={() => setUi({ collapsed: true, panel: '' })} />
      <Tool b={b} on={tool === 'pen'} onClick={() => setUi({ tool: 'pen', panel: ui.panel === 'pens' ? '' : 'pens' })}>
        <div className={`w-[${Math.round(b * 0.6)}px] h-[${Math.round(b * 0.6)}px] rounded-full flex items-center justify-center bg-[${inkOf(color)}] ${T.swatch}`}>
          <div className={`w-[${dot}px] h-[${dot}px] rounded-full ${color.toLowerCase() === '#ffffff' ? 'bg-black' : 'bg-white'}`} />
        </div>
      </Tool>
      <Tool b={b} d={ICONS.eraser} on={tool === 'eraser'} onClick={() => setUi({ tool: 'eraser', panel: ui.panel === 'pens' ? '' : ui.panel })} />
      <Tool b={b} d={ICONS.undo} off={!canUndo} onClick={undo} />
      <Tool b={b} d={ICONS.redo} off={!canRedo} onClick={redo} />
      <Tool b={b} d={ICONS.menu} onClick={() => setUi({ panel: ui.panel === 'menu' ? '' : 'menu', asking: '' })}>
        <Icon d={ICONS.menu} className={`w-[${Math.round(b * 0.5)}px] h-[${Math.round(b * 0.5)}px]`} />
        {dirty ? <div className={`absolute top-[8px] right-[8px] w-[10px] h-[10px] rounded-full ${T.dot}`} /> : null}
      </Tool>
    </div>
  )
})

// Pens and brush sizes, next to the rail.
const PensPanel = ({ b, x, y }) => {
  const list = pens()
  const cols = hc ? 2 : 5
  const sw = Math.round(b * 0.82)
  return (
    <div className={`absolute left-[${x}px] ${y < 0 ? `bottom-[${-y}px]` : `top-[${y}px]`} flex flex-col gap-[${z(12)}px] p-[${z(12)}px] ${T.panel}`} onPointerDown={() => {}}>
      <div className={`grid grid-cols-${cols} gap-[${z(8)}px]`}>
        {list.map((color, i) => (
          <div className={`flex flex-col items-center ${hc ? 'gap-1' : ''}`} onClick={() => setUi({ pen: i, tool: 'pen', panel: '' })}>
            <div className={`w-[${sw}px] h-[${sw}px] rounded-full bg-[${color}] ${ui.pen === i && ui.tool === 'pen' ? T.swatchOn : T.swatch}`} />
            {hc ? <span className={`text-[${z(14)}px] font-semibold`}>{i === 0 ? 'Black' : 'White'}</span> : null}
          </div>
        ))}
      </div>
      <div className={`flex gap-[${z(8)}px]`}>
        {SIZES.map((size, i) => (
          <div className={`w-[${sw}px] h-[${sw}px] flex items-center justify-center rounded-xl ${ui.size === i ? T.sizeOn : T.size}`}
            onClick={() => setUi({ size: i, panel: '' })}>
            <div className={`w-[${Math.max(3, Math.round((size / 24) * sw * 0.7))}px] h-[${Math.max(3, Math.round((size / 24) * sw * 0.7))}px] rounded-full ${ui.size === i ? (hc ? 'bg-white' : 'bg-slate-900') : hc ? 'bg-black' : 'bg-white'}`} />
          </div>
        ))}
      </div>
      <span className={`text-[${z(14)}px]`}>{`${hc ? (ui.pen === 0 ? 'Black' : 'White') : PEN_NAMES[ui.pen] || ''} · ${SIZE_NAMES[ui.size]}`}</span>
    </div>
  )
}

// ---------------------------------------------------------------- sheets

const sheetSize = () => [Math.min(W - 24, z(560)), Math.min(H - 24, z(460))]

const MenuSheet = () => {
  const [w, h] = sheetSize()
  const close = () => setUi({ panel: '' })
  const dirty = doc.rev !== doc.saved && doc.strokes.length > 0
  const status = doc.name
    ? `${pathOf(doc.name)}${dirty ? ' · changes not saved' : ''}`
    : doc.strokes.length ? 'Not saved yet' : 'An empty page'
  if (ui.asking === 'new' || ui.asking === 'clear') {
    const isNew = ui.asking === 'new'
    return (
      <Sheet t={T} w={w} onClose={close}>
        <SheetBar t={T} title={isNew ? 'Start a new drawing?' : 'Clear the drawing?'} onClose={close} />
        <div className={`flex flex-col p-[${z(16)}px] gap-[${z(16)}px]`}>
          <span className={`text-[${z(18)}px]`}>{isNew
            ? (dirty ? 'The changes since it was last saved are lost.' : 'The page is put away; saved files stay.')
            : 'Every stroke goes. The picture under it stays.'}</span>
          <div className={`flex gap-[${z(12)}px]`}>
            <div className="flex-1"><Action t={T} label="Cancel" onClick={() => setUi({ asking: '' })} /></div>
            <div className="flex-1">
              <Action t={T} kind="danger" d={isNew ? ICONS.plus : ICONS.broom} label={isNew ? 'New drawing' : 'Clear'} onClick={() => {
                if (isNew) replaced(blank(W, H))
                else replaced(Object.assign({}, doc, { strokes: [], rev: (doc.rev || 0) + 1 }))
                setUi({ panel: '', asking: '', note: isNew ? 'A new page' : 'Cleared' })
              }} />
            </div>
          </div>
        </div>
      </Sheet>
    )
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={T} title={doc.name || 'Untitled drawing'} sub={status} onClose={close} />
      <div className={`grid grid-cols-2 gap-[${z(12)}px] p-[${z(16)}px]`}>
        <Action t={T} d={ICONS.save} kind="primary" label="Save" onClick={() => {
          if (doc.name) {
            if (save(doc.name)) setUi({ panel: '' })
          } else setUi({ panel: 'save', draft: freshName(), asking: '' })
        }} />
        <Action t={T} d={ICONS.file} label="Save as…" onClick={() => setUi({ panel: 'save', draft: doc.name || freshName(), asking: '' })} />
        <Action t={T} d={ICONS.folder} label="Open…" onClick={() => setUi({ panel: 'open', asking: '' })} />
        <Action t={T} d={ICONS.plus} label="New" onClick={() => {
          if (doc.strokes.length || doc.bg) setUi({ asking: 'new' })
          else setUi({ panel: '' })
        }} />
        <Action t={T} d={ICONS.image} label="Picture…" onClick={() => setUi({ panel: 'picture', asking: '' })} />
        <Action t={T} d={ICONS.broom} label="Clear…" onClick={() => setUi({ asking: doc.strokes.length ? 'clear' : '' })} />
      </div>
      {ui.note ? <div className={`mx-[${z(16)}px] mb-[${z(16)}px] px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${T.button}`}>{ui.note}</div> : null}
    </Sheet>
  )
}

const OpenSheet = () => {
  const [w, h] = sheetSize()
  const files = listFiles(folder, ['.svg'])
  const close = () => setUi({ panel: '', asking: '' })
  return (
    <Sheet t={T} w={w} h={h} onClose={close}>
      <SheetBar t={T} title="Open a drawing" sub={`${folder}/ · ${files.length} ${files.length === 1 ? 'file' : 'files'}`}
        onBack={() => setUi({ panel: 'menu', asking: '' })} onClose={close} />
      <div className={`flex-1 overflow-y-auto p-[${z(12)}px]`}>
        <div className={`flex flex-col gap-[${z(8)}px]`}>
          {files.length === 0 ? <span className={`p-[${z(12)}px] text-[${z(18)}px] ${T.muted}`}>{`Nothing saved in ${folder} yet.`}</span> : null}
          {files.map((path) => {
            const name = stripExt(baseName(path))
            return (
              <FileRow t={T} d={ICONS.file} name={name} sub={name === doc.name ? 'Open now' : ''} asking={ui.asking === path}
                onOpen={() => open(path)}
                onAsk={() => setUi({ asking: path })}
                onCancel={() => setUi({ asking: '' })}
                onDelete={() => {
                  frameos.deleteAsset(path)
                  if (name === doc.name) {
                    doc.name = ''
                    commit()
                  }
                  setUi({ asking: '', note: `Deleted ${baseName(path)}` })
                }} />
            )
          })}
        </div>
      </div>
    </Sheet>
  )
}

const SaveSheet = () => {
  const [w, h] = sheetSize()
  const close = () => setUi({ panel: '', asking: '' })
  const name = safeName(ui.draft)
  const trySave = (replace) => {
    if (!name) {
      note('Give it a name first')
      return
    }
    if (!replace && name !== doc.name && frameos.assetExists(pathOf(name))) {
      setUi({ asking: 'replace' })
      return
    }
    if (save(name)) setUi({ panel: '', asking: '' })
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={T} title="Save the drawing" sub={`as an SVG file in ${folder}/`} onBack={() => setUi({ panel: 'menu', asking: '' })} onClose={close} />
      <div className={`flex flex-col gap-[${z(12)}px] p-[${z(16)}px]`}>
        {ui.asking === 'replace' ? (
          <div className={`flex flex-col gap-[${z(12)}px]`}>
            <span className={`text-[${z(18)}px]`}>{`"${name}" is there already. Replace it?`}</span>
            <div className={`flex gap-[${z(12)}px]`}>
              <div className="flex-1"><Action t={T} label="Cancel" onClick={() => setUi({ asking: '' })} /></div>
              <div className="flex-1"><Action t={T} kind="danger" label="Replace" onClick={() => trySave(true)} /></div>
            </div>
          </div>
        ) : (
          <NameForm t={T} value={ui.draft} placeholder="Name" label="Save"
            onChange={(v) => setUi({ draft: v, note: '' })} onSave={() => trySave(false)} />
        )}
        {ui.note ? <span className={`text-[${z(16)}px] ${T.muted}`}>{ui.note}</span> : null}
      </div>
    </Sheet>
  )
}

// A picture from the assets folder under the drawing, a folder at a time.
const PictureSheet = () => {
  const [w, h] = sheetSize()
  const close = () => setUi({ panel: '', asking: '' })
  const here = ui.browse || ''
  const { folders, files } = listFolder(here, IMAGES)
  const up = here.includes('/') ? here.slice(0, here.lastIndexOf('/')) : ''
  return (
    <Sheet t={T} w={w} h={h} onClose={close}>
      <SheetBar t={T} title="Draw over a picture" sub={here ? `${here}/` : 'The assets folder'}
        onBack={() => setUi({ panel: 'menu' })} onClose={close} />
      <div className={`flex-1 overflow-y-auto p-[${z(12)}px]`}>
        <div className={`flex flex-col gap-[${z(8)}px]`}>
          {doc.bg ? (
            <FileRow t={T} d={ICONS.close} name="No picture" sub={`Now: ${doc.bg}`} onOpen={() => {
              replaced(Object.assign({}, doc, { bg: '', rev: (doc.rev || 0) + 1 }))
              setUi({ panel: '' })
            }} />
          ) : null}
          {here ? <FileRow t={T} d={ICONS.up} name="Up" sub={up ? `${up}/` : 'The assets folder'} onOpen={() => setUi({ browse: up })} /> : null}
          {folders.slice(0, 200).map((path) => (
            <FileRow t={T} d={ICONS.folder} name={baseName(path)} onOpen={() => setUi({ browse: path.replace(/\/$/, '') })} />
          ))}
          {files.slice(0, 200).map((path) => (
            <FileRow t={T} d={ICONS.image} name={baseName(path)} sub={path === doc.bg ? 'Under the drawing now' : ''} onOpen={() => {
              replaced(Object.assign({}, doc, { bg: path, rev: (doc.rev || 0) + 1 }))
              setUi({ panel: '', note: `Drawing over ${baseName(path)}` })
            }} />
          ))}
          {!folders.length && !files.length ? <span className={`p-[${z(12)}px] text-[${z(18)}px] ${T.muted}`}>No pictures here (PNG or JPEG).</span> : null}
        </div>
      </div>
    </Sheet>
  )
}

// ------------------------------------------------------------------- get

export function get(app, context) {
  W = Math.round(context.imageWidth ?? app.frame.width)
  H = Math.round(context.imageHeight ?? app.frame.height)
  k = Math.max(1, Math.min(4, app.frame.scale || 1))
  if (W * k * H * k > 4096 * 4096) k = 1
  CW = Math.round(W * k)
  CH = Math.round(H * k)
  hc = highContrast(app)
  T = hc ? THEMES.high : THEMES.color
  setZoom(Math.max(1, Math.min(2, Math.min(W, H) / 480)))
  paper = hexColor(app.state.paper) || '#fbf8f1'
  folder = safeFolder(app.state.folder, 'Drawings')
  doc = loadDoc(app, W, H)
  ui = loadUi()
  if (ui.size < 0 || ui.size >= SIZES.length) ui.size = Math.max(0, Math.min(3, (parseInt(app.state.brush) || 2) - 1))
  if (ui.pen >= pens().length) ui.pen = 0
  live = frameos.recall('live') || null
  fitView()

  canvas = frameos.canvas('sketch', CW, CH, T.desk)
  if (!canvas) {
    return (
      <div className="flex items-center justify-center w-full h-full p-8 bg-white text-black text-2xl text-center">
        Not enough memory for a page this size.
      </div>
    )
  }
  // Drawn again when the canvas is new or anything it was drawn from changed.
  const look = [hc, paper, doc.bg, CW, CH, doc.w, doc.h, doc.gen].join('|')
  if (canvas.fresh || frameos.recall('look') !== look) {
    paintAll()
    frameos.remember('look', look)
  }

  const across = H > W // a tall screen: the tools along the bottom
  const lefty = app.state.hand === 'left'
  const b = Math.max(44, Math.min(110, Math.round(Math.min(W, H) * 0.115)))
  const railLong = 6 * b + 5 * 6 + 12
  const margin = Math.round(b * 0.15)
  const railX = across ? Math.round((W - railLong) / 2) : lefty ? W - margin - (b + 12) : margin
  const railY = across ? H - margin - (b + 12) : Math.round((H - railLong) / 2)
  const canUndo = doc.strokes.length > 0
  const canRedo = redoStack().length > 0
  const dirty = doc.rev !== doc.saved && doc.strokes.length > 0
  // The pens panel, beside the rail (above it on a tall screen: a negative
  // y is a distance from the bottom).
  const sw = Math.round(b * 0.82)
  const panelW = Math.max((hc ? 2 : 5) * sw + (hc ? 1 : 4) * z(8), 4 * sw + 3 * z(8)) + 2 * z(12)
  const swatchRows = hc ? 1 : 2
  const panelH = sw * (swatchRows + 1) + (swatchRows - 1) * z(8) + (hc ? z(24) : 0) + z(20) + 2 * z(12) + 2 * z(12)
  const panelX = across ? Math.max(8, Math.min(W - panelW - 8, railX + b + 12)) : lefty ? railX - panelW - 8 : railX + b + 12 + 8
  const panelY = across ? -(H - railY + 8) : Math.max(8, Math.min(H - panelH - 8, railY + b))

  return (
    <div className={`w-[${W}px] h-[${H}px] bg-[${T.desk}]`}>
      <img className={`w-[${W}px] h-[${H}px]`} src={canvas}
        onPointerDown={startStroke} onPointerMove={moveStroke} onPointerUp={endStroke} />
      {!doc.strokes.length && !doc.bg && !live && !ui.panel ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <span className={`text-[${z(24)}px] ${T.hint}`}>Draw with a finger</span>
        </div>
      ) : null}
      {ui.collapsed ? (
        <div className={`absolute ${lefty ? `right-[${margin}px]` : `left-[${margin}px]`} ${across ? `bottom-[${margin}px]` : `top-[${margin}px]`} p-[6px] ${T.rail}`}
          onPointerDown={() => {}}>
          <Tool b={b} d={ICONS.brush} onClick={() => setUi({ collapsed: false })} />
        </div>
      ) : (
        <div className={`absolute left-[${railX}px] top-[${railY}px]`}>
          <Rail b={b} across={across} lefty={lefty} tool={ui.tool} pen={ui.pen} size={ui.size} canUndo={canUndo} canRedo={canRedo} dirty={dirty} hcLook={hc} />
        </div>
      )}
      {ui.panel === 'pens' && !ui.collapsed ? <PensPanel b={b} x={panelX} y={panelY} /> : null}
      {ui.note && !ui.panel ? (
        <div className="absolute top-[12px] left-0 right-0 flex justify-center">
          <div className={`px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] max-w-[${Math.round(W * 0.7)}px] ${T.note}`} onPointerDown={() => {}}
            onClick={() => setUi({ note: '' })}>{ui.note}</div>
        </div>
      ) : null}
      {ui.panel === 'menu' ? <MenuSheet /> : null}
      {ui.panel === 'open' ? <OpenSheet /> : null}
      {ui.panel === 'save' ? <SaveSheet /> : null}
      {ui.panel === 'picture' ? <PictureSheet /> : null}
    </div>
  )
}

// Buttons and keys: back is undo, forward redo (a swipe in from the left or
// right edge on a touch screen), and Ctrl+Z / Ctrl+Y on a keyboard.
export function onEvent(app, context) {
  if (!doc) doc = loadDoc(app, W, H)
  if (!ui) ui = loadUi()
  const key = context.payload?.key || ''
  if (context.event === 'back' || (context.event === 'keyDown' && context.payload?.ctrl && key.toLowerCase() === 'z')) {
    undo()
    return true
  }
  if (context.event === 'forward' || (context.event === 'keyDown' && context.payload?.ctrl && key.toLowerCase() === 'y')) {
    redo()
    return true
  }
  return false
}

