// Files in the frame's assets folder: names, UTF-8 to base64 for
// frameos.writeAsset, and a small, forgiving reader for the SVG files this
// scene writes (and simple ones written elsewhere).

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

// Text as UTF-8 bytes in base64: what frameos.writeAsset takes. QuickJS has
// no btoa or TextEncoder here, so this is both, a few characters at a time.
export const toBase64 = (text: string): string => {
  const parts = []
  let chunk = ''
  let a = -1
  let b = -1
  // Three bytes make four characters.
  const push = (byte: number) => {
    if (a < 0) a = byte
    else if (b < 0) b = byte
    else {
      const n = (a << 16) | (b << 8) | byte
      chunk += B64[n >> 18] + B64[(n >> 12) & 63] + B64[(n >> 6) & 63] + B64[n & 63]
      a = -1
      b = -1
      if (chunk.length > 4096) {
        parts.push(chunk)
        chunk = ''
      }
    }
  }
  for (let i = 0; i < text.length; i++) {
    let c = text.charCodeAt(i)
    if (c >= 0xd800 && c < 0xdc00 && i + 1 < text.length) {
      c = 0x10000 + ((c - 0xd800) << 10) + (text.charCodeAt(++i) - 0xdc00)
    }
    if (c < 0x80) push(c)
    else if (c < 0x800) {
      push(0xc0 | (c >> 6))
      push(0x80 | (c & 63))
    } else if (c < 0x10000) {
      push(0xe0 | (c >> 12))
      push(0x80 | ((c >> 6) & 63))
      push(0x80 | (c & 63))
    } else {
      push(0xf0 | (c >> 18))
      push(0x80 | ((c >> 12) & 63))
      push(0x80 | ((c >> 6) & 63))
      push(0x80 | (c & 63))
    }
  }
  if (a >= 0) {
    const n = (a << 16) | ((b < 0 ? 0 : b) << 8)
    chunk += B64[n >> 18] + B64[(n >> 12) & 63] + (b < 0 ? '=' : B64[(n >> 6) & 63]) + '='
  }
  parts.push(chunk)
  return parts.join('')
}

// For text inside an XML file (a title, an attribute).
export const xml = (text: string): string =>
  String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')

const unxml = (text: string): string =>
  text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')

// A name typed on the frame as a file name: no folders, no characters a
// file system refuses, no leading dot (hidden files are never listed).
export const safeName = (name: string): string =>
  String(name || '')
    .replace(/[\/\\:*?"<>|\u0000-\u001f]/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/^[\s.]+/, '')
    .trim()
    .slice(0, 60)
    .trim()

// "Drawings" from a setting: no leading or trailing slashes, no "..".
export const safeFolder = (folder: string, fallback: string): string => {
  const parts = String(folder || '')
    .split('/')
    .map((part) => safeName(part))
    .filter((part) => part && part !== '..')
  return parts.length ? parts.join('/') : fallback
}

export const baseName = (path: string): string => path.replace(/\/$/, '').split('/').pop() || ''
export const stripExt = (name: string): string => name.replace(/\.[^.]+$/, '')

// The files of one folder whose names end in one of `exts`, sorted by name.
// An app without the assets permission, or a frame before 2026.11.8, gets [].
export const listFiles = (folder: string, exts: string[]): string[] => {
  let entries = []
  try {
    entries = frameos.listAssets(folder, { shallow: true }) || []
  } catch (e) {
    entries = []
  }
  return entries.filter((path) => {
    const lower = path.toLowerCase()
    return !lower.endsWith('/') && exts.some((ext) => lower.endsWith(ext))
  })
}

// A folder's entries: its folders, then the files with one of `exts`.
export const listFolder = (folder: string, exts: string[]) => {
  let entries = []
  try {
    entries = frameos.listAssets(folder, { shallow: true }) || []
  } catch (e) {
    entries = []
  }
  const folders = entries.filter((path) => path.endsWith('/'))
  const files = entries.filter((path) => {
    const lower = path.toLowerCase()
    return !lower.endsWith('/') && exts.some((ext) => lower.endsWith(ext))
  })
  return { folders, files }
}

export const writeText = (path: string, text: string): boolean => {
  try {
    return frameos.writeAsset(path, toBase64(text)) === true
  } catch (e) {
    return false
  }
}

export const readText = (path: string, length?: number): string | null => {
  try {
    return frameos.readAsset(path, length ? { text: true, length } : { text: true })
  } catch (e) {
    return null
  }
}

// ------------------------------------------------------------ reading SVG

// The attributes of one tag's text (`<polyline points="1 2" stroke='red'>`),
// names lowercased; a style="stroke: red" is read as attributes too.
export const tagAttrs = (tag: string): Record<string, string> => {
  const attrs: Record<string, string> = {}
  const re = /([\w:.-]+)\s*=\s*("([^"]*)"|'([^']*)')/g
  let m
  while ((m = re.exec(tag))) {
    attrs[m[1].toLowerCase()] = unxml(m[3] !== undefined ? m[3] : m[4])
  }
  if (attrs.style) {
    for (const rule of attrs.style.split(';')) {
      const at = rule.indexOf(':')
      if (at > 0) {
        const key = rule.slice(0, at).trim().toLowerCase()
        if (key && attrs[key] === undefined) attrs[key] = rule.slice(at + 1).trim()
      }
    }
  }
  return attrs
}

// Every element of these names, in order, as [name, attributes]. Comments
// and anything else are skipped; this is a reader for our own simple files,
// not a full XML parser.
export const svgElements = (text: string, names: string[]): [string, Record<string, string>][] => {
  const out = []
  const clean = text.replace(/<!--[\s\S]*?-->/g, '')
  const re = /<([a-zA-Z][\w:-]*)\b([^>]*)>/g
  let m
  while ((m = re.exec(clean))) {
    const name = m[1].toLowerCase()
    if (names.includes(name)) out.push([name, tagAttrs(m[2])])
  }
  return out
}

// The root <svg>'s attributes, and its size from viewBox (else width/height).
export const svgRoot = (text: string) => {
  // (?:svg): the scene linter reads a plain "<" + "svg" in code as markup to check.
  const m = /<(?:svg)\b([^>]*)>/i.exec(text)
  if (!m) return null
  const attrs = tagAttrs(m[1])
  let x = 0
  let y = 0
  let w = parseFloat(attrs.width)
  let h = parseFloat(attrs.height)
  const box = (attrs.viewbox || '').split(/[\s,]+/).map(Number)
  if (box.length === 4 && box.every((n) => isFinite(n)) && box[2] > 0 && box[3] > 0) {
    ;[x, y, w, h] = box
  }
  if (!(w > 0) || !(h > 0)) return null
  return { attrs, x, y, w, h }
}

// The text of the first <title>, if any.
export const svgTitle = (text: string): string => {
  const m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(text)
  return m ? unxml(m[1]).trim() : ''
}

// Numbers in a points list or a path ("10,20 30 40" -> [10, 20, 30, 40]).
export const numbers = (text: string): number[] =>
  (String(text || '').match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) || []).map(Number)

// A path's points, for paths made of moves and lines (M, L, H, V, Z, in
// either case); a curve's end point stands in for the curve. Each M starts
// a new run. Good enough for strokes drawn elsewhere as simple paths.
export const pathRuns = (d: string): number[][] => {
  const runs = []
  let run = null
  let x = 0
  let y = 0
  const tokens = String(d || '').match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) || []
  let cmd = ''
  let i = 0
  const num = () => Number(tokens[i++])
  const isNum = () => i < tokens.length && !/^[a-zA-Z]$/.test(tokens[i])
  const add = () => {
    if (!run) {
      run = []
      runs.push(run)
    }
    run.push(x, y)
  }
  while (i < tokens.length) {
    if (/^[a-zA-Z]$/.test(tokens[i])) cmd = tokens[i++]
    else if (!cmd) {
      i++
      continue
    }
    const rel = cmd === cmd.toLowerCase()
    const c = cmd.toUpperCase()
    if (c === 'Z') {
      if (run && run.length >= 2) run.push(run[0], run[1])
      continue
    }
    // How many numbers each command takes; its end point is the last pair.
    const take = { M: 2, L: 2, T: 2, H: 1, V: 1, C: 6, S: 4, Q: 4, A: 7 }[c]
    if (!take) {
      i++
      continue
    }
    if (!isNum()) continue
    const args = []
    for (let k = 0; k < take && isNum(); k++) args.push(num())
    if (args.length < take) break
    if (c === 'H') x = rel ? x + args[0] : args[0]
    else if (c === 'V') y = rel ? y + args[0] : args[0]
    else {
      x = rel ? x + args[take - 2] : args[take - 2]
      y = rel ? y + args[take - 1] : args[take - 1]
    }
    if (c === 'M') {
      run = null
      add()
      cmd = rel ? 'l' : 'L' // more pairs after a move are lines
    } else add()
  }
  return runs.filter((r) => r.length >= 2)
}

// A color as #rrggbb, or '' for none: hex (#abc, #aabbcc), rgb(), and a few names.
const NAMED = {
  black: '#000000', white: '#ffffff', red: '#ff0000', green: '#008000', blue: '#0000ff',
  yellow: '#ffff00', orange: '#ffa500', purple: '#800080', gray: '#808080', grey: '#808080',
}
export const hexColor = (value: string): string => {
  const v = String(value || '').trim().toLowerCase()
  if (!v || v === 'none' || v === 'transparent') return ''
  if (NAMED[v]) return NAMED[v]
  let m = /^#([0-9a-f]{3})$/.exec(v)
  if (m) return '#' + m[1].split('').map((c) => c + c).join('')
  m = /^#([0-9a-f]{6})([0-9a-f]{2})?$/.exec(v)
  if (m) return '#' + m[1]
  m = /^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/.exec(v)
  if (m) return '#' + [m[1], m[2], m[3]].map((n) => Math.min(255, Number(n)).toString(16).padStart(2, '0')).join('')
  return ''
}

// "2026-11-18 14:05" in the frame's time zone (Date is local time there).
export const stamp = (time: number): string => {
  const d = new Date(time)
  const two = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())} ${two(d.getHours())}:${two(d.getMinutes())}`
}

