// Geometry of strokes: a stroke is [color, width, x0, y0, x1, y1, ...] in
// the drawing's own units. Boxes are [x0, y0, x1, y1].

export type Stroke = (string | number)[]

// The box a stroke covers, its width included.
export const strokeBox = (stroke: Stroke): number[] => {
  const half = Number(stroke[1]) / 2 + 1
  let x0 = Infinity
  let y0 = Infinity
  let x1 = -Infinity
  let y1 = -Infinity
  for (let i = 2; i + 1 < stroke.length; i += 2) {
    const x = stroke[i] as number
    const y = stroke[i + 1] as number
    if (x < x0) x0 = x
    if (x > x1) x1 = x
    if (y < y0) y0 = y
    if (y > y1) y1 = y
  }
  return [x0 - half, y0 - half, x1 + half, y1 + half]
}

export const unionBox = (a: number[] | null, b: number[]): number[] =>
  a ? [Math.min(a[0], b[0]), Math.min(a[1], b[1]), Math.max(a[2], b[2]), Math.max(a[3], b[3])] : b.slice()

export const boxesMeet = (a: number[], b: number[]): boolean =>
  a[0] <= b[2] && b[0] <= a[2] && a[1] <= b[3] && b[1] <= a[3]

// How far (x, y) is from the segment (ax, ay)-(bx, by).
export const segmentDistance = (x: number, y: number, ax: number, ay: number, bx: number, by: number): number => {
  const dx = bx - ax
  const dy = by - ay
  const len = dx * dx + dy * dy
  let t = len > 0 ? ((x - ax) * dx + (y - ay) * dy) / len : 0
  t = t < 0 ? 0 : t > 1 ? 1 : t
  const px = ax + t * dx - x
  const py = ay + t * dy - y
  return Math.sqrt(px * px + py * py)
}

// Whether a stroke passes within `reach` of (x, y), its own width included.
export const strokeNear = (stroke: Stroke, x: number, y: number, reach: number): boolean => {
  const r = reach + Number(stroke[1]) / 2
  if (stroke.length <= 4) {
    const dx = (stroke[2] as number) - x
    const dy = (stroke[3] as number) - y
    return dx * dx + dy * dy <= r * r
  }
  for (let i = 2; i + 3 < stroke.length; i += 2) {
    if (segmentDistance(x, y, stroke[i] as number, stroke[i + 1] as number, stroke[i + 2] as number, stroke[i + 3] as number) <= r) {
      return true
    }
  }
  return false
}

// The round-capped band a segment of width 2r paints, as horizontal strips
// `step` tall: [x, y, w, h] each. Clipped to these, a picture can be put
// back where an eraser went, which no SVG clip path could do here.
export const capsuleStrips = (ax: number, ay: number, bx: number, by: number, r: number, step: number): number[][] => {
  const strips = []
  // Rows on a grid of `step`, so the strips of neighbouring segments line
  // up and can be merged (mergeStrips).
  const top = Math.floor((Math.min(ay, by) - r) / step) * step
  const bottom = Math.ceil(Math.max(ay, by) + r)
  // Where a horizontal line at y enters and leaves the band: the end
  // circles' chords and the sides of the rectangle between them.
  const span = (y: number): number[] | null => {
    let lo = Infinity
    let hi = -Infinity
    for (const [cx, cy] of [[ax, ay], [bx, by]]) {
      const dy = y - cy
      if (dy * dy <= r * r) {
        const half = Math.sqrt(r * r - dy * dy)
        lo = Math.min(lo, cx - half)
        hi = Math.max(hi, cx + half)
      }
    }
    const dx = bx - ax
    const dy = by - ay
    const len = Math.sqrt(dx * dx + dy * dy)
    if (len > 0) {
      const nx = (-dy / len) * r
      const ny = (dx / len) * r
      const corners = [[ax + nx, ay + ny], [bx + nx, by + ny], [bx - nx, by - ny], [ax - nx, ay - ny]]
      for (let i = 0; i < 4; i++) {
        const [x0, y0] = corners[i]
        const [x1, y1] = corners[(i + 1) % 4]
        if ((y0 <= y && y <= y1) || (y1 <= y && y <= y0)) {
          const x = y1 === y0 ? Math.min(x0, x1) : x0 + ((y - y0) / (y1 - y0)) * (x1 - x0)
          const x2 = y1 === y0 ? Math.max(x0, x1) : x
          lo = Math.min(lo, x, x2)
          hi = Math.max(hi, x, x2)
        }
      }
    }
    return hi >= lo ? [lo, hi] : null
  }
  for (let y = top; y < bottom; y += step) {
    // The strip is as wide as the band anywhere in it: its edges and middle.
    let lo = Infinity
    let hi = -Infinity
    for (const at of [y, y + step / 2, Math.min(y + step, bottom)]) {
      const s = span(at)
      if (s) {
        lo = Math.min(lo, s[0])
        hi = Math.max(hi, s[1])
      }
    }
    if (hi > lo) strips.push([Math.floor(lo), y, Math.ceil(hi) - Math.floor(lo), step])
  }
  return strips
}

// Strips of many segments, those of a row that overlap or touch joined:
// an eraser stroke as a few rects a row rather than a dozen a segment.
export const mergeStrips = (strips: number[][]): number[][] => {
  const rows = {}
  for (const strip of strips) (rows[strip[1]] = rows[strip[1]] || []).push(strip)
  const out = []
  for (const key of Object.keys(rows)) {
    const row = rows[key].sort((a, b) => a[0] - b[0])
    let cur = row[0].slice()
    for (let i = 1; i < row.length; i++) {
      const next = row[i]
      if (next[0] <= cur[0] + cur[2]) cur[2] = Math.max(cur[2], next[0] + next[2] - cur[0])
      else {
        out.push(cur)
        cur = next.slice()
      }
    }
    out.push(cur)
  }
  return out
}

// Points kept in all strokes.
export const pointCount = (strokes: Stroke[]): number => {
  let n = 0
  for (const s of strokes) n += (s.length - 2) / 2
  return n
}

